       if(x<RW-1&&(n=i+1,!seen[n]&&reduced[n]>=220)){seen[n]=1;queue[tail++]=n}
       if(y>0&&(n=i-RW,!seen[n]&&reduced[n]>=220)){seen[n]=1;queue[tail++]=n}
       if(y<RH-1&&(n=i+RW,!seen[n]&&reduced[n]>=220)){seen[n]=1;queue[tail++]=n}
